import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------- CUDA kernel -----------------------
cuda_source = r'''
extern "C" __global__
void group_norm_forward(const half* __restrict__ input,
                        half* __restrict__ output,
                        const half* __restrict__ weight,
                        const half* __restrict__ bias,
                        const int N,
                        const int C,
                        const int H,
                        const int W,
                        const int G,
                        const float eps) {
    // each block handles one (n, g) pair
    const int n = blockIdx.x;
    const int g = blockIdx.y;
    const int tid = threadIdx.x;

    const int C_per_g = C / G;
    const int numel = C_per_g * H * W;          // elements in this group

    // ---------- first pass: compute sum & sumsq ----------
    float sum = 0.0f;
    float sumsq = 0.0f;

    for (int idx = tid; idx < numel; idx += blockDim.x) {
        int i = idx;
        int w = i % W;      i /= W;
        int h = i % H;      i /= H;
        int c = i;          // 0 .. C_per_g-1

        int global_c = g * C_per_g + c;
        int offset = ((n * C + global_c) * H + h) * W + w;

        half hv = __ldg(&input[offset]);
        float fv = __half2float(hv);
        sum   += fv;
        sumsq += fv * fv;
    }

    // reduction in shared memory
    __shared__ float sh_sum[1024];
    __shared__ float sh_sumsq[1024];
    sh_sum[tid]   = sum;
    sh_sumsq[tid] = sumsq;
    __syncthreads();

    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh_sum[tid]   += sh_sum[tid + stride];
            sh_sumsq[tid] += sh_sumsq[tid + stride];
        }
        __syncthreads();
    }

    const float mean = sh_sum[0] / numel;
    const float var  = sh_sumsq[0] / numel - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    // ---------- second pass: normalize & apply affine ----------
    for (int idx = tid; idx < numel; idx += blockDim.x) {
        int i = idx;
        int w = i % W;      i /= W;
        int h = i % H;      i /= H;
        int c = i;          // 0 .. C_per_g-1

        int global_c = g * C_per_g + c;
        int offset = ((n * C + global_c) * H + h) * W + w;

        float fv = __half2float(input[offset]);
        float norm = (fv - mean) * inv_std;

        float wgt = __half2float(weight[global_c]);
        float b   = __half2float(bias[global_c]);

        float out = norm * wgt + b;
        output[offset] = __float2half(out);
    }
}
'''

# Compile the kernel
gn_mod = load_inline(name='group_norm_cuda',
                     cpp_sources='',
                     cuda_sources=cuda_source,
                     functions=['group_norm_forward'],
                     verbose=False)

# ----------------------- PyTorch wrapper -----------------------
class GroupNormFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, weight, bias, num_groups, eps):
        assert input.is_cuda and input.dtype == torch.float16
        N, C, H, W = input.shape
        output = torch.empty_like(input)

        # launch kernel
        threads = 256
        blocks = (N, num_groups)
        gn_mod.group_norm_forward(
            input,
            output,
            weight,
            bias,
            N, C, H, W,
            num_groups,
            float(eps),
            grid=blocks,
            block=(threads, 1, 1),
            stream=torch.cuda.current_stream().cuda_stream
        )
        # save for backward (optional – not implemented)
        ctx.save_for_backward(input, weight, bias)
        ctx.num_groups = num_groups
        ctx.eps = eps
        return output

    @staticmethod
    def backward(ctx, grad_output):
        # For simplicity, fall back to PyTorch's autograd by recomputing
        # with built‑in GroupNorm; this ensures gradients are correct.
        input, weight, bias = ctx.saved_tensors
        gn = nn.GroupNorm(ctx.num_groups, input.shape[1], eps=ctx.eps, affine=True).to(input.device, dtype=torch.float16)
        gn.weight = weight
        gn.bias = bias
        input.requires_grad = True
        out = gn(input)
        out.backward(grad_output)
        return input.grad, weight.grad, bias.grad, None, None

# ----------------------- Model using custom kernel -----------------------
class ModelNew(nn.Module):
    """
    GroupNorm implemented with a custom CUDA kernel (fp16).
    """
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5):
        super().__init__()
        self.num_groups = num_groups
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16, device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16, device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            x = x.half()
        return GroupNormFunction.apply(x, self.weight, self.bias, self.num_groups, self.eps)

# ----------------------- Helper for testing -----------------------
def get_inputs():
    x = torch.rand(112, 64, 512, 512, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return [64, 8]   # num_features, num_groups

if __name__ == "__main__":
    # Simple sanity check against PyTorch's GroupNorm
    feats, groups = get_init_inputs()
    model_ref = nn.GroupNorm(groups, feats).cuda().half()
    model_new = ModelNew(feats, groups)

    x = get_inputs()[0]
    out_ref = model_ref(x)
    out_new = model_new(x)

    torch.testing.assert_allclose(out_new, out_ref, atol=1e-2, rtol=1e-2)
    print("Forward pass matches reference implementation.")
